  "sql": "SELECT i.snapshot_date AS snapshot_date, p.product_id AS product_id, p.product_name AS product_name, i.days_of_supply AS days_of_supply FROM commerce.inventory AS i JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date = (SELECT MAX(j.snapshot_date) FROM commerce.inventory AS j) AND i.days_of_supply IS NOT NULL ORDER BY i.days_of_supply ASC, p.product_id ASC LIMIT 200",
